-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["f6048b46f10166f2"] = { "Saluti, fratello o sorella. La Shattered Hand ti porge i suoi omaggi e spera che troverai la Valle un luogo comodo in cui esercitare il tuo mestiere. Per te questo è un tempo di prove, perciò non illuderti che nessuno ti tenga d'occhio: ti osserviamo di continuo.\n\nÈ mio compito riferire alla Shattered Hand le tue abilità, e poi avvisarla quando riterrò che tu possa passare a sfide più grandi.\n\nQuando te la senti, vieni a cercarmi in fondo all'Antro del Tirocinio. Ti aspetterò lì.\n\n-Rwag, istruttore dei ladri", "." },
  ["f63128548234a5fd"] = { "Rapporto sulla situazione dei troll ⟦Frostmane=Mantogelido⟧ nell'area generale di Dun Morogh\n\nI troll stanziati a Dun Morogh sono per lo più concentrati nel ⟦Frostmane Hold=Covo dei Mantogelido⟧, una caverna montana sul confine occidentale. Sono abbastanza numerosi da destare una certa preoccupazione, ma sembrano più che contenti di restare nella loro caverna. Questo, senza dubbio, perché non desiderano attirarsi di nuovo l'ira dei nani e rischiare lo sterminio totale. Le loro azioni, semmai, si possono considerare territoriali, ed è", "." },
  ["f66b2d2e2f6a2600"] = { "Una situazione terribile in cui trovarci, non è vero, {name}? Tormentati dal Principe Immondo. Emarginati e respinti dai nostri stessi cari. Finalmente abbiamo una volontà nostra grazie alla splendida Sylvanas, ma che cosa ci concede ora? Lo schiavo di un altro padrone resta pur sempre uno schiavo, o almeno così dico io.\n\nMa se fossimo noi i padroni? Sì, sai cosa intendo, vero?\n\nSiamo ancora più separati dal resto dei Reietti, {name}. Ed è per questo che dobbiamo parlarne ancora. Cercami nella chiesa di ⟦Deathknell=Albamorta⟧.", "." },
  ["f66bf81ea0c85b84"] = { "PORTARE A SPASSO IL TUO TARTASNIFFO\n\nIl tartasniffo ama i posti piccoli e bui. Ed è molto timido.\n\nSe vuoi portare a spasso il tuo tartasniffo, devi portarlo in un posto che gli sembri casa. E DEVI portarlo dove possa sentire l'odore del suo cibo preferito: i tuberi di foglia blu!\n\nIl posto più vicino di questo tipo è la zona della \"trincea\" delle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧. Se apri la cassetta vicino alla trincea e il tuo tartasniffo sente l'odore di qualche tubero nei dintorni, si avventurerà fuori e ti seguirà.", "." },
  ["f670b01919b9bf49"] = { "Rimasero immobili, come congelati, e lei sostenne i loro sguardi con calma. Poi un cavaliere alzò gli occhi, come se udisse un richiamo lontano. Estrasse dalle vesti una piccola gemma e vi scrutò dentro. Poi, con il gioiello, fece un gesto verso la moglie di Sven. Una luce strisciò dal Cavaliere verso la donna, prendendo la forma di una sinistra mano bianca. Lei fissò la luce senza battere ciglio, ma potevo vedere l'incertezza dietro la sua maschera di sicurezza. Quando la mano la raggiunse, allargò le dita sulla sua testa.\n\nE strinse.", "." },
  ["f67b6ee200df28cb"] = { "Ottimo lavoro, compare! Ora devi andare dritto a est. A est su per le scogliere, a est fino alla strada. Cerca i resti del vecchio camino sul ciglio della strada. Lì troverai un vecchio barile con il prossimo indizio.", "." },
  ["f698bcaa544d6c48"] = { "Pochi giorni dopo il mio arrivo al fienile, Sven lasciò la fattoria per andare a ⟦Darkshire=Borgoscuro⟧. Baciò la moglie, sorrise ai figli e promise di tornare presto con giocattoli e dolci. Pover'uomo. Fu l'ultima volta che vide la sua famiglia ancora intatta.\n\nAlmeno si separarono felici. E almeno sua moglie fu la prima a morire, e le fu risparmiata la vista del massacro dei suoi figli. Ma queste piccole grazie non fanno nulla per me. Ho visto cosa è successo, e tormenterà per sempre i miei sogni.", "." },
  ["f6c0b889b9341d5b"] = { "Il sangue versato vicino al pendente di sanguinite si muoveva lentamente verso il gioiello, come se la gravità si fosse in qualche modo piegata verso la sanguinite. Il sangue che toccava il pendente sembrava scomparire, e il rosso della pietra si faceva più intenso man mano che beveva il mio sangue.", "." },
})
